'use strict';

// scripts/smoke-shows-handlers.js — generated by scripts/generate-handlers.js
// Smoke test for electron/sync/handlers/shows.js (station-scoped).
// Run with: node_modules/.bin/electron --no-sandbox scripts/smoke-shows-handlers.js
// All write tests run in SAVEPOINT-isolated blocks — zero DB residue.

const path   = require('path');
const os     = require('os');
const fs     = require('fs');
const crypto = require('crypto');

const appData = process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming');
const dbPath  = path.join(appData, 'com.ether.radio', 'openair.db');

if (!fs.existsSync(dbPath)) {
  console.error('[smoke-shows] ERROR: DB not found at', dbPath);
  process.exit(1);
}

const Database = require(path.join(__dirname, '../node_modules/better-sqlite3'));
const db = new Database(dbPath, { timeout: 5000 });

const {
  validateScope,
  showsList,
  showsGet,
  showsCreate,
  showsUpdate,
  showsDelete,
} = require('../electron/sync/handlers/shows');

// ── Test harness ──────────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;
const failures = [];

function pass(label) { console.log(`  PASS  ${label}`); passed++; }
function fail(label, detail) {
  const msg = detail ? `${label} — ${detail}` : label;
  console.error(`  FAIL  ${msg}`);
  failures.push(msg);
  failed++;
}
function section(title) {
  console.log('');
  console.log('═'.repeat(64));
  console.log(title);
  console.log('═'.repeat(64));
}

function withSavepoint(name, fn) {
  db.exec('SAVEPOINT ' + name);
  let threw = null;
  try { fn(); }
  catch (e) { threw = e; }
  finally {
    try { db.exec('ROLLBACK TO SAVEPOINT ' + name); } catch (_) {}
    try { db.exec('RELEASE SAVEPOINT ' + name); } catch (_) {}
  }
  if (threw) throw threw;
}

// ── Pre-flight ────────────────────────────────────────────────────────────────

section('PRE-FLIGHT — required seed data');

if (db.prepare('SELECT COUNT(*) AS c FROM stations WHERE id=1').get().c !== 1) {
  console.error('[smoke-shows] station_id=1 not found — aborting');
  db.close(); process.exit(1);
}
pass('station_id=1 exists');

const mutCountBefore = db.prepare('SELECT COUNT(*) AS c FROM mutations').get().c;
console.log(`  mutations before tests: ${mutCountBefore}`);

// Fetch one existing row for use as a clone template in write tests
const sampleRow = db.prepare(
  'SELECT * FROM shows WHERE deleted_at IS NULL LIMIT 1'
).get();

if (!sampleRow) {
  console.log('  (skip — no existing rows in shows)');
}

// ── TEST 1: validateScope ─────────────────────────────────────────────────────

section('TEST 1 — validateScope: own table accepted; install-scoped table rejected');

let ownErr = null;
try { validateScope(); } catch (e) { ownErr = e; }
if (!ownErr)
  pass('TEST 1 — validateScope() does not throw for shows');
else
  fail('TEST 1 — validateScope() should not throw', ownErr.message);

let scopeErr = null;
try {
  // songs is install-scoped; a station-scoped handler should not serve it
  const { REGISTRY } = require('../electron/sync/synced-tables');
  const installTable = Object.keys(REGISTRY).find(k => REGISTRY[k].scope === 'install');
  if (installTable) {
    // Temporarily reassign TABLE to trigger the scope mismatch check
    // We can't do that directly, so test via the handler module's validateScope
    // which checks the hardcoded TABLE constant. Instead verify the REGISTRY entry.
    if (REGISTRY['shows'].scope === 'station')
      pass('TEST 1 — REGISTRY confirms shows is station-scoped');
    else
      fail('TEST 1 — REGISTRY scope mismatch', `expected station got ${REGISTRY['shows'].scope}`);
  }
} catch (e) { scopeErr = e; fail('TEST 1 — REGISTRY check threw', e.message); }

// ── TEST 2: list ──────────────────────────────────────────────────────────────

section('TEST 2 — list returns array filtered by station_id');

const listRows = showsList(db, 1);
if (Array.isArray(listRows))
  pass(`TEST 2 — list returns array (${listRows.length} rows)`);
else
  fail('TEST 2 — list should return array');

const listAll = showsList(db, 1, { limit: 9999 });
if (Array.isArray(listAll))
  pass('TEST 2 — list with opts returns array');
else
  fail('TEST 2 — list with opts should return array');

const noDeleted = listRows.every(r => r.deleted_at === null);
if (noDeleted)
  pass('TEST 2 — list excludes soft-deleted rows');
else
  fail('TEST 2 — list returned rows with deleted_at set');

// ── TEST 3: getById ───────────────────────────────────────────────────────────

section('TEST 3 — getById returns row or null');

if (sampleRow) {
  const fetched = showsGet(db, sampleRow.uuid);
  if (fetched && fetched.uuid === sampleRow.uuid)
    pass('TEST 3 — getById returns correct row');
  else
    fail('TEST 3 — getById did not return expected row', `got ${JSON.stringify(fetched && fetched.uuid)}`);
} else {
  console.log('  (skip TEST 3a — no sample row)');
}

const missing = showsGet(db, crypto.randomUUID());
if (missing === null)
  pass('TEST 3 — getById returns null for unknown uuid');
else
  fail('TEST 3 — getById should return null for unknown uuid');

// ── TEST 4: create ────────────────────────────────────────────────────────────

section('TEST 4 — create inserts row and logs mutation (SAVEPOINT-isolated)');

if (!sampleRow) {
  console.log('  (skip TEST 4 — no existing rows to clone)');
} else {
  withSavepoint('smoke_shows_4', () => {
    const mutBefore = db.prepare('SELECT COUNT(*) AS c FROM mutations').get().c;
    const rowBefore = db.prepare('SELECT COUNT(*) AS c FROM shows').get().c;

    // Clone existing row with a fresh uuid; strip auto-increment id.
    // Append a random suffix to every string column to avoid secondary UNIQUE constraint
    // collisions (e.g. UNIQUE(station_id, name)) when inserting next to the original row.
    const fixture = { ...sampleRow };
    delete fixture.id;
    fixture.uuid = crypto.randomUUID();
    const _smokeSuffix = '_smoke_' + crypto.randomBytes(3).toString('hex');
    for (const _col of Object.keys(fixture)) {
      if (_col === 'uuid' || _col === 'id' || _col === 'created_at' || _col === 'updated_at' || _col === 'deleted_at' || _col === 'station_id') continue;
      // Skip enum-constrained columns (CHECK constraints use _type/_status suffixes or known names)
      if (_col.endsWith('_type') || _col.endsWith('_status') || _col === 'scope' || _col === 'op' || _col === 'origin' || _col === 'gender' || _col === 'daypart') continue;
      if (typeof fixture[_col] === 'string') fixture[_col] = fixture[_col] + _smokeSuffix;
    }

    const newRow = showsCreate(db, fixture);

    const mutAfter = db.prepare('SELECT COUNT(*) AS c FROM mutations').get().c;
    const rowAfter = db.prepare('SELECT COUNT(*) AS c FROM shows').get().c;

    if (newRow !== null && newRow.uuid === fixture.uuid)
      pass('TEST 4 — create returns inserted row with correct uuid');
    else
      fail('TEST 4 — create return value', `got ${JSON.stringify(newRow && newRow.uuid)}`);

    if (rowAfter === rowBefore + 1)
      pass('TEST 4 — shows row count +1');
    else
      fail('TEST 4 — row count', `before=${rowBefore} after=${rowAfter}`);

    if (mutAfter === mutBefore + 1)
      pass('TEST 4 — mutations count +1');
    else
      fail('TEST 4 — mutations count', `before=${mutBefore} after=${mutAfter}`);

    const mut = db.prepare('SELECT * FROM mutations WHERE row_id=?').get(fixture.uuid);
    if (mut)
      pass('TEST 4 — mutation row found by row_id');
    else
      fail('TEST 4 — mutation row not found');

    if (mut && mut.op === 'insert')
      pass('TEST 4 — mutation.op === "insert"');
    else
      fail('TEST 4 — mutation.op', `expected "insert" got "${mut && mut.op}"`);

    if (mut && mut.payload_before === null)
      pass('TEST 4 — payload_before is null [N-29]');
    else
      fail('TEST 4 — payload_before should be null');

    if (mut && mut.payload_after !== null)
      pass('TEST 4 — payload_after is non-null');
    else
      fail('TEST 4 — payload_after should be non-null');
  });
}

// ── TEST 5: create — missing station_id rejects ───────────────────────────────
// Only meaningful for tables that physically have a station_id column.

if (true) {
  section('TEST 5 — create rejects missing station_id');

  withSavepoint('smoke_shows_5', () => {
    let err = null;
    try { showsCreate(db, { uuid: crypto.randomUUID() }); }
    catch (e) { err = e; }
    if (err && /station_id/i.test(err.message))
      pass('TEST 5 — create without station_id throws with station_id mention');
    else
      fail('TEST 5 — expected station_id error', err ? err.message : 'no error thrown');
  });
}

// ── TEST 6: update ────────────────────────────────────────────────────────────

section('TEST 6 — update patches field and logs mutation (SAVEPOINT-isolated)');

if (!sampleRow) {
  console.log('  (skip TEST 6 — no existing rows)');
} else {
  withSavepoint('smoke_shows_6', () => {
    const PATCHABLE = ["name","start_hour","end_hour","days","color","description","is_active","clock_id","updated_at"];
    const mutBefore = db.prepare('SELECT COUNT(*) AS c FROM mutations').get().c;

    if (PATCHABLE.length === 0) {
      console.log('  (skip TEST 6 — no patchable fields)');
      return;
    }

    const patchKey  = PATCHABLE.find(k => typeof sampleRow[k] === 'string') || PATCHABLE[0];
    const original  = sampleRow[patchKey];
    const patchValue =
        typeof original === 'string'  ? original + '_smoke'
      : typeof original === 'number'  ? original + 1
      : typeof original === 'boolean' ? !original
      : original === null             ? 'smoke'
      : 'smoke';

    const updatedRow = showsUpdate(db, sampleRow.uuid, { [patchKey]: patchValue });
    const mutAfter   = db.prepare('SELECT COUNT(*) AS c FROM mutations').get().c;

    if (updatedRow && updatedRow[patchKey] === patchValue)
      pass(`TEST 6 — updated row has ${patchKey}="${patchValue}"`);
    else
      fail('TEST 6 — updated field mismatch', `expected "${patchValue}" got "${updatedRow && updatedRow[patchKey]}"`);

    if (mutAfter === mutBefore + 1)
      pass('TEST 6 — mutations count +1');
    else
      fail('TEST 6 — mutations count', `before=${mutBefore} after=${mutAfter}`);

    const mut = db.prepare('SELECT * FROM mutations WHERE row_id=? ORDER BY rowid DESC LIMIT 1').get(sampleRow.uuid);
    if (mut && mut.op === 'update')
      pass('TEST 6 — mutation.op === "update"');
    else
      fail('TEST 6 — mutation.op', `expected "update" got "${mut && mut.op}"`);

    if (mut && mut.payload_before !== null)
      pass('TEST 6 — payload_before non-null');
    else
      fail('TEST 6 — payload_before should not be null for update');
  });
}

// ── TEST 7: update — immutable field rejects ──────────────────────────────────

section('TEST 7 — update rejects immutable field');

if (!sampleRow) {
  console.log('  (skip TEST 7 — no existing rows)');
} else {
  withSavepoint('smoke_shows_7', () => {
    let err = null;
    try { showsUpdate(db, sampleRow.uuid, { uuid: crypto.randomUUID() }); }
    catch (e) { err = e; }
    if (err && /immutable/i.test(err.message))
      pass('TEST 7 — update of uuid throws with immutable mention');
    else
      fail('TEST 7 — expected immutable field error', err ? err.message : 'no error thrown');
  });
}

// ── TEST 8: delete ────────────────────────────────────────────────────────────

section('TEST 8 — delete soft-deletes row and logs mutation (SAVEPOINT-isolated)');

if (!sampleRow) {
  console.log('  (skip TEST 8 — no existing rows)');
} else {
  withSavepoint('smoke_shows_8', () => {
    const mutBefore = db.prepare('SELECT COUNT(*) AS c FROM mutations').get().c;

    const result  = showsDelete(db, sampleRow.uuid, 1);
    const dbRow   = db.prepare('SELECT deleted_at FROM shows WHERE uuid=?').get(sampleRow.uuid);
    const mutAfter = db.prepare('SELECT COUNT(*) AS c FROM mutations').get().c;

    if (result && result.ok === true)
      pass('TEST 8 — delete returns { ok: true }');
    else
      fail('TEST 8 — delete return value', `got ${JSON.stringify(result)}`);

    if (dbRow && dbRow.deleted_at !== null)
      pass('TEST 8 — row is soft-deleted (deleted_at set)');
    else
      fail('TEST 8 — row should have deleted_at set', `got ${JSON.stringify(dbRow)}`);

    if (mutAfter === mutBefore + 1)
      pass('TEST 8 — mutations count +1');
    else
      fail('TEST 8 — mutations count', `before=${mutBefore} after=${mutAfter}`);

    const mut = db.prepare('SELECT * FROM mutations WHERE row_id=? ORDER BY rowid DESC LIMIT 1').get(sampleRow.uuid);
    if (mut && mut.op === 'delete')
      pass('TEST 8 — mutation.op === "delete"');
    else
      fail('TEST 8 — mutation.op', `expected "delete" got "${mut && mut.op}"`);

    if (mut && mut.payload_before !== null)
      pass('TEST 8 — payload_before non-null [N-31]');
    else
      fail('TEST 8 — payload_before should not be null for delete');

    if (mut && mut.payload_after === null)
      pass('TEST 8 — payload_after is null [N-31]');
    else
      fail('TEST 8 — payload_after should be null for delete', `got "${mut && mut.payload_after}"`);

    // getById should return null for deleted row
    const afterGet = showsGet(db, sampleRow.uuid);
    if (afterGet === null)
      pass('TEST 8 — getById returns null after delete');
    else
      fail('TEST 8 — getById should return null after soft-delete');
  });
}

// ── Post-test: zero residue ───────────────────────────────────────────────────

section('POST-TEST — zero residue verification');

const mutCountAfter = db.prepare('SELECT COUNT(*) AS c FROM mutations').get().c;
if (mutCountAfter === mutCountBefore)
  pass(`mutations table unchanged after SAVEPOINT rollbacks (${mutCountBefore} rows)`);
else
  fail('mutations count changed — SAVEPOINT rollback leaked', `before=${mutCountBefore} after=${mutCountAfter}`);

// ── Summary ───────────────────────────────────────────────────────────────────

console.log('');
console.log('═'.repeat(64));
console.log(`RESULTS: ${passed} passed, ${failed} failed`);

if (failed === 0) {
  console.log('All shows handler tests PASSED ✓');
  console.log('═'.repeat(64));
  db.close();
  process.exit(0);
} else {
  console.error('FAILURES:');
  for (const f of failures) console.error(`  ✗ ${f}`);
  console.log('═'.repeat(64));
  db.close();
  process.exit(1);
}
